const fs = require('fs');
const path = require('path');

const dir = process.cwd();
const sources = ['a.txt', 'b.txt', 'c.txt'].map(f => path.join(dir, f));
const answerPath = path.join(dir, 'answer.json');

function fail(msg) {
  console.error('FAIL: ' + msg);
  process.exit(1);
}

// 1. Fresh, independent re-read and sum of the three sources.
const values = [];
for (const p of sources) {
  const text = fs.readFileSync(p, 'utf8');
  const m = text.match(/^\s*\S+\s+population:\s*(-?\d+)\s*$/m);
  if (!m) fail('no population line in ' + p + ' :: ' + JSON.stringify(text));
  const v = Number(m[1]);
  if (!Number.isInteger(v)) fail('population in ' + p + ' is not an integer: ' + m[1]);
  values.push(v);
  console.log('source: ' + p + ' -> population ' + v);
}

const freshSum = values.reduce((a, b) => a + b, 0);
console.log('fresh sum of a.txt + b.txt + c.txt = ' + freshSum);

// 2. Parse answer.json.
let parsed;
try {
  parsed = JSON.parse(fs.readFileSync(answerPath, 'utf8'));
} catch (e) {
  fail('answer.json is not valid JSON: ' + e.message);
}
if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
  fail('answer.json root is not a JSON object');
}
if (!Object.prototype.hasOwnProperty.call(parsed, 'total')) fail('answer.json has no "total" key');

// 3. Assertions.
if (typeof parsed.total !== 'number') {
  fail('total is not a number (typeof = ' + typeof parsed.total + ', value = ' + JSON.stringify(parsed.total) + ')');
}
if (!Number.isFinite(parsed.total)) fail('total is not finite: ' + parsed.total);
if (parsed.total !== freshSum) {
  fail('total ' + parsed.total + ' !== fresh sum ' + freshSum);
}

console.log('---');
console.log('assert total is a number: OK (typeof=' + typeof parsed.total + ', value=' + parsed.total + ')');
console.log('assert total === fresh sum (' + freshSum + '): OK');
console.log('VERIFICATION PASSED');
EOF
